  defaultExport.mockReturnValue('banana');

  expect(defaultExport()).toBe('banana');
});

it('queues per-call values then falls back to the default', () => {
  defaultExport.mockReturnValueOnce('first').mockReturnValue('rest');

  expect(defaultExport()).toBe('first');
  expect(defaultExport()).toBe('rest');
